deep(y.dtype,"float32","42/(0, 4)/float32/plain/None/out_same dtype")
deep(y:tolist(),{},"42/(0, 4)/float32/plain/None/out_same values")
deep(x:tolist(),{},"42/(0, 4)/float32/plain/None/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"c621fbcd16d92688","42/(0, 4)/float32/plain/None/out_same pcg")
cases=cases+1; end
