deep(y.dtype,"float32","42/(0, 4)/float32/flip/-1/copy dtype")
deep(y:tolist(),{},"42/(0, 4)/float32/flip/-1/copy values")
deep(x:tolist(),{},"42/(0, 4)/float32/flip/-1/copy source")
deep(r:raw_hex(),"c621fbcd16d92688","42/(0, 4)/float32/flip/-1/copy pcg")
cases=cases+1; end
