local x=np.transpose(np.astype(np.arange(0,"int64"):reshape({2,0}),"uint8"),{2,1})
local before=x:tolist()
local y=r:permuted(x,2,x)
deep(y.dtype,"uint8","42/(2, 0)/uint8/transpose/1/out_same dtype")
deep(y:tolist(),{},"42/(2, 0)/uint8/transpose/1/out_same values")
deep(x:tolist(),{},"42/(2, 0)/uint8/transpose/1/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"c621fbcd16d92688","42/(2, 0)/uint8/transpose/1/out_same pcg")
cases=cases+1; end
